input.sparql:
SELECT ?zone ?ts WHERE {
  ?zone a brick:Zone ; brick:hasSensor ?sensor .
  ?sensor a brick:AirTemperatureSensor .
  ?sensor ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?ts .
  OPTIONAL { ?zone rdfs:label ?zone }
}

SELECT DISTINCT ?zone ?name ?sensor ?ts WHERE {
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?name }
  ?zone brick:hasSensor ?sensor .
  ?sensor ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?ts .
  FILTER(?name != ?zone)
} LIMIT 50

